{
  "name": "Luminos 电动旋转轴",
  "name_en": "Luminos motorized rotation axis",
  "manufacturer": "Zaber Technologies",
  "description": "用于 Luminos 多轴精密定位平台的电动旋转轴，可提供滚转、偏航或俯仰等角度调节。该类装置常用于光学对准、样品姿态调整、器件耦合和自动化精密定位实验。",
  "description_en": "A motorized rotational axis used in Luminos multi-axis precision positioning stages, providing angular adjustment such as roll, yaw, or pitch. It is commonly used for optical alignment, sample orientation, device coupling, and automated precision positioning in laboratory setups.",
  "tag_hints": [
    "motorized rotation stage",
    "precision angular positioning",
    "optical alignment",
    "multi-axis positioning",
    "pitch yaw roll control",
    "microstepping",
    "automated sample alignment"
  ],
  "actions": [
    {
      "action_name": "auto-arc_second_per_step",
      "description": "获取每步对应的角秒值。",
      "description_en": "Get arcseconds per step."
    },
    {
      "action_name": "auto-home",
      "description": "使旋转轴回到原点位置。",
      "description_en": "Home the rotation axis."
    },
    {
      "action_name": "auto-set_default_settings",
      "description": "恢复该轴的默认设置。",
      "description_en": "Restore the axis default settings."
    },
    {
      "action_name": "auto-set_manual_mode",
      "description": "将该轴设置为手动模式。",
      "description_en": "Set the axis to manual mode."
    },
    {
      "action_name": "auto-set_computer_mode",
      "description": "将该轴设置为计算机控制模式。",
      "description_en": "Set the axis to computer-control mode."
    },
    {
      "action_name": "auto-flash_leds",
      "description": "闪烁该轴的指示灯。",
      "description_en": "Flash the axis LEDs."
    },
    {
      "action_name": "auto-move_rel",
      "description": "按相对角位移移动该轴。",
      "description_en": "Move the axis by a relative angular offset."
    },
    {
      "action_name": "auto-move_abs",
      "description": "将该轴移动到绝对角位置。",
      "description_en": "Move the axis to an absolute angular position."
    },
    {
      "action_name": "auto-get_device_mode_bit_status",
      "description": "获取设备模式位状态。",
      "description_en": "Get the device mode bit status."
    },
    {
      "action_name": "auto-turn_leds_off",
      "description": "关闭该轴的指示灯。",
      "description_en": "Turn the axis LEDs off."
    },
    {
      "action_name": "auto-turn_leds_on",
      "description": "打开该轴的指示灯。",
      "description_en": "Turn the axis LEDs on."
    },
    {
      "action_name": "auto-enable_motor_knob",
      "description": "启用电机旋钮手动控制。",
      "description_en": "Enable motor knob control."
    },
    {
      "action_name": "auto-disable_motor_knob",
      "description": "禁用电机旋钮手动控制。",
      "description_en": "Disable motor knob control."
    },
    {
      "action_name": "auto-enable_manual_move_reply",
      "description": "启用手动移动回报。",
      "description_en": "Enable manual move reply."
    },
    {
      "action_name": "auto-disable_manual_move_reply",
      "description": "禁用手动移动回报。",
      "description_en": "Disable manual move reply."
    },
    {
      "action_name": "auto-enable_circular_phase_microstepping",
      "description": "启用圆相位微步功能。",
      "description_en": "Enable circular-phase microstepping."
    },
    {
      "action_name": "auto-disable_circular_phase_microstepping",
      "description": "禁用圆相位微步功能。",
      "description_en": "Disable circular-phase microstepping."
    },
    {
      "action_name": "auto-enable_anti_backlash_routine",
      "description": "启用消隙例程。",
      "description_en": "Enable the anti-backlash routine."
    },
    {
      "action_name": "auto-disable_anti_backlash_routine",
      "description": "禁用消隙例程。",
      "description_en": "Disable the anti-backlash routine."
    },
    {
      "action_name": "auto-enable_anti_sticktion_routine",
      "description": "启用防静摩擦例程。",
      "description_en": "Enable the anti-stiction routine."
    },
    {
      "action_name": "auto-disable_anti_sticktion_routine",
      "description": "禁用防静摩擦例程。",
      "description_en": "Disable the anti-stiction routine."
    },
    {
      "action_name": "auto-enable_move_tracking",
      "description": "启用移动跟踪功能。",
      "description_en": "Enable move tracking."
    },
    {
      "action_name": "auto-disable_move_tracking",
      "description": "禁用移动跟踪功能。",
      "description_en": "Disable move tracking."
    },
    {
      "action_name": "auto-get_speed",
      "description": "获取速度设置。",
      "description_en": "Get the speed setting."
    },
    {
      "action_name": "auto-set_speed",
      "description": "设置速度。",
      "description_en": "Set the speed."
    },
    {
      "action_name": "auto-get_acceleration",
      "description": "获取加速度设置。",
      "description_en": "Get the acceleration setting."
    },
    {
      "action_name": "auto-set_acceleration",
      "description": "设置加速度。",
      "description_en": "Set the acceleration."
    },
    {
      "action_name": "auto-get_microstep_resolution",
      "description": "获取微步分辨率。",
      "description_en": "Get microstep resolution."
    },
    {
      "action_name": "auto-set_microstep_resolution",
      "description": "设置微步分辨率。",
      "description_en": "Set microstep resolution."
    },
    {
      "action_name": "auto-nm_per_step",
      "description": "获取每步对应的纳米位移值。",
      "description_en": "Get nanometers per step."
    }
  ]
}

